const telegramResponse = $input.first().json;
const updates = Array.isArray(telegramResponse.result) ? telegramResponse.result : [];
const configuredUserId = Number($env.SAGE_TELEGRAM_ALLOWED_USER_ID);
const configuredChatId = Number($env.SAGE_TELEGRAM_CHAT_ID);
const configuredTopicIds = new Set([Number($env.SAGE_TELEGRAM_MAIN_TOPIC_ID), Number($env.SAGE_TELEGRAM_REPORTS_TOPIC_ID), Number($env.SAGE_TELEGRAM_NOTIFICATIONS_TOPIC_ID)]);
const supportedMimeTypes = new Set(['image/jpeg', 'image/png', 'image/webp', 'application/pdf']);
const latestUpdateId = updates.reduce((latestId, update) => Math.max(latestId, Number(update.update_id) || 0), 0);
const messages = updates.flatMap((update) => {
  const callback = update.callback_query;
  if (callback?.message && callback.from?.id === configuredUserId && callback.message.chat?.id === configuredChatId && configuredTopicIds.has(callback.message.message_thread_id)) {
    return [{ json: { endpoint: '/v1/telegram/callbacks', payload: { callbackId: callback.id, chatId: callback.message.chat.id, data: callback.data, messageThreadId: callback.message.message_thread_id, senderId: callback.from.id } } }];
  }
  const message = update.message;
  if (!message || message.from?.id !== configuredUserId || message.chat?.id !== configuredChatId || message.message_thread_id !== Number($env.SAGE_TELEGRAM_MAIN_TOPIC_ID)) return [];
  const largestPhoto = Array.isArray(message.photo) && message.photo.length > 0 ? message.photo[message.photo.length - 1] : null;
  const document = message.document && supportedMimeTypes.has(message.document.mime_type) ? message.document : null;
  const attachment = largestPhoto ? { fileId: largestPhoto.file_id, fileName: `${largestPhoto.file_unique_id}.jpg`, fileSize: largestPhoto.file_size, fileUniqueId: largestPhoto.file_unique_id, kind: 'PHOTO', mimeType: 'image/jpeg' } : document ? { fileId: document.file_id, fileName: document.file_name || document.file_unique_id, fileSize: document.file_size, fileUniqueId: document.file_unique_id, kind: 'DOCUMENT', mimeType: document.mime_type } : null;
  const messageText = typeof message.text === 'string' ? message.text : typeof message.caption === 'string' ? message.caption : '';
  if (!messageText && !attachment) return [];
  return [{ json: { endpoint: '/v1/telegram/messages', payload: { attachment, chatId: message.chat.id, messageId: message.message_id, messageThreadId: message.message_thread_id, senderId: message.from.id, text: messageText } } }];
});
const workflowState = $getWorkflowStaticData('global');
if (latestUpdateId > 0) {
  if (messages.length === 0) { workflowState.nextUpdateOffset = latestUpdateId + 1; delete workflowState.pendingUpdateOffset; }
  else { workflowState.pendingUpdateOffset = latestUpdateId + 1; }
}
return messages;

const workflowState = $getWorkflowStaticData('global');
if (typeof workflowState.pendingUpdateOffset === 'number') {
  workflowState.nextUpdateOffset = workflowState.pendingUpdateOffset;
  delete workflowState.pendingUpdateOffset;
}
return $input.all();
